CustomField.formula:
IF(ISPICKVAL(Cost_Period__c, 'Annual'), 
    Total_Days_Active__c * (Cost__c/365), 
    IF(ISPICKVAL(Cost_Period__c, 'Monthly'), 
        Total_Months_Active__c * (Cost__c), 
        IF(ISPICKVAL(Cost_Period__c, 'Daily'), 
            Total_Days_Active__c * (Cost__c), 
            0.00
        )
    )
)
